.expandBtn {
    float: right;
    padding: 10px;
    margin: 10px 0px;
    border: none;
    background: transparent;
    color: #fff;

    display: flex;
    align-items: center;
    justify-content: end;
    cursor: pointer;
}

.navItems--bottom {
    margin-top: auto;
}

.navLogout {
    margin-top: auto;
    background: transparent;
    border: none;
    width: 100%;
    color: #fff;
    padding: 30px 15px;
    font-size: 15px;
    text-align: center;
    border-top: 1px solid #636363;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;

}

.dashboard-organisationSelector {
    border: none;
    padding: 0px 17px;
    background: transparent;
    color: #fff;
    font-size: 12px;
    appearance: none;
    -webkit-appearance: none;
    position: relative;
}

.dashboard-organisationSelector:focus,
.dashboard-organisationSelector:focus-within,
.dashboard-organisationSelector:focus-visible {
    outline: none;
}

.dashboard-organisationContainer {
    position: relative;
}

.dashboard-profile__nameContainer {
    width: 250px;
    margin-right: 20px;
    text-align: right;
}

.arrowRight {
    width: 10px;
    height: 10px;
    display: inline-block;
    margin-left: 10px;

}

.company_container {
    display: flex;
    justify-content: center;
    align-items: center;
}

.company_container .selectorContianer {
    margin-right: 20px;
}

.logo_container {
    display: flex;
    align-items: center
}

.logo-selector-container {
    display: flex;
    align-items: center;
}

.menu {
    display: none;
}

@media screen and (min-width: 320px) and (max-width: 900px) {
    .dashboard-header {
        width: 100%;
        max-height: max-content;
        padding-right: 0;
    }

    .main-grid {
        padding-top: 131px;
    }

    .menu {
        display: block;
        padding: 10px;
        cursor: pointer;
        background-color: transparent;
        border: none;
        color: #fff;
    }

    .menu-bar{
        width: 25px;
        height: 3px;
        background-color: #fff;
        margin: 5px auto;
        transition: all .3s ease-in-out;
        border-radius: 5px;
    }

    .logo-selector-container {
        display: block;
    }

        .company_container .selectorContianer{
        margin-right: 0px;
        }

    .company_container {
        flex-direction: row;
        align-items: flex-start;
        padding-bottom: 10px;
        padding-right: 0;
        gap: 10px;
    }

    .grid-3 {
        grid-template-columns: 1fr;
    }

    .grid-container {
        display: block;
    }

    .dashboard-profile {
        align-items: flex-start;
    }

    .dashboard-profile__nameContainer {
        width: auto;
    }

    .navOverlay {
        display: none;
    }

    .dashboard-header>.dashboard-profile .content-img {
        margin: 0 5px 5px auto;
    }

    .platform-view {
        border: none;
        padding: 0;
        margin: 0;
    }

    .infoHeader {
        position: relative;
    }

    .infoHeader.sticky {
        top: 130px;
    }

    .infoHeader .dashboard-content {
        grid-template-columns: .5fr 1fr !important;
    }

    .infoHeader .crawl-cta {
