    padding-block: 60px;
}

.loginForm-body{
    margin: 0;
    padding: 0;
    font-family: 'Arial', sans-serif;
    background-color: #f0f0f0;
}
.signin-container{
    display: flex;
    flex-direction: column;
    place-content: center;
    background-color: #ffffff;
    color: #636363;
}

.loginForm-container {
    display: grid;
    grid-template-columns: 1fr .65fr;
    min-height: 70vh;
    height: auto;
    width: 100%;
}

.loginForm-header{
    background-image: radial-gradient(circle, #c09f53, #856a2b);
    color: #ffffff;
    display: grid;
    place-content: center;
    line-height: 1.4;
    grid-template-rows: 1fr;
    overflow: hidden;
}

.loginForm-header-content{
    margin: auto;
    width: 550px;
    padding-block: 40px;
}

.loginForm-header-content h1{
    font-size: 2em;
    font-weight: 600;
    margin: 0;
}

.loginForm-signup{
    padding: 10px 20px;
    background-color: #ffffff;
    color: #636363;
    display: flex;
    flex-direction: column;
    justify-content: center;
    border: 1px solid #c09f53;
    border-radius: 30px;
    margin: 10px;
    text-decoration: none;
    font-size: 16px;
}

.loginForm-signup-2{
    text-decoration: none;
    color: #636363;
    margin-top: 20px;
    border-radius: 30px;
    padding: 10px 20px;
}

.loginForm-signup-2:hover, .loginForm-signup:hover{
    background-color: #c09f53;
    color: #ffffff;
    transition: all 0.3s ease;
    border: 1px solid #c09f53;
    cursor: pointer;
}

.loginForm-overlay {
    position: fixed;
    top: 0;
    z-index: 100;
    width: 100%;
    height: 100%;
    margin: auto;
    display: grid;
    place-content: center;
    background: rgba(0, 0, 0, .7);
}

.loginForm {
    width: 100%;
    height: 100%;
    margin: auto;
    background: radial-gradient(circle at top, rgba(188, 188, 188, .8) -10%, rgba(48, 48, 48, .6));
    padding: 80px;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    justify-content: center;
    color: rgb(234, 234, 234);
    backdrop-filter: saturate(180%) blur(20px);
    -webkit-backdrop-filter: saturate(180%) blur(20px);
    grid-column: 2/3;
}

.loginForm-overlay .loginForm {
    width: 500px;
}

.loginForm label {
    text-align: left;
    display: block;
    padding: 5px 0px;
}

.loginForm-inputField {
    padding: 15px;
    border: none;
    width: 100%;
    box-sizing: border-box;
    font-size: 16px;
    margin: 2px 0px;
}

.loginForm-forget {
    padding: 15px;
    color: rgb(234, 234, 234);
    text-decoration: none;
    display: block;
    text-align: right;
}

.loginForm-logo {
    width: 350px;
    margin-bottom: 30px;
}

.loginForm-logo.--hideMobile {
    display: none;
}

.intastellar-accounts-logo{
    width: 120px;
    margin-top: 170px;
}


.loginForm-inputField.--btn {
    background-color: #c09f53;
    font-size: 16px;
    color: #fff;
    font-weight: bold;
    letter-spacing: 5px;
    text-transform: uppercase;
}

.loginForm-title {
    font-size: 1.175em;
    text-align: center;
    padding: 15px 0px;
}

.loginForm-service {
    margin: 0 0 10px;
}

.loginForm-inputField.--link {
    color: #fff;
    text-decoration: none;
    font-size: 14px;
    text-align: center;
    display: block;
    margin: 10px 0px;
}

.graphic-container{
    height: 100%;
}

.main-content-section{
    padding: 50px;
    color: #636363;
}

.used_by {
    display: inline-block;
    width: 50%;
    height: 100px;
    object-fit: contain;
    object-position: center;
    margin-inline: 50px;
}

.feature-list{
    width: 1100px;
    margin-inline: auto;
}

.testimonials{
    display: grid;
    grid-template-columns: repeat(4, 1fr);
}

.key-numbers-section{
    padding-block: 150px;
    background-color: #fff;
}

@media screen and (min-width: 375px) and (max-width: 900px) {
    .loginForm-container {
        grid-template-columns: 1fr;
    }

    .loginForm-logo {
        width: 50%;
        padding: 0;
        margin: 20px auto;
    }

    .loginForm-title{
        font-size: 1.1em;
        width: 100%;
        margin: 0 auto;
    }

        .loginForm-header{
        grid-template-columns: 1fr;
        }

    .loginForm-header-content{
        width: 100%;
        padding: 20px;
    }

    .loginForm {
        padding: 40px;
        background: radial-gradient(circle at top, rgba(188, 188, 188, .6) -10%, rgba(48, 48, 48, .4));
    }

    .loginForm-container {
        background-position: -250px;
        height: auto;
    }

    .signup {
        overflow: scroll;
    }

    .loginForm-header, .signin-container{
        height: auto !important;
    }

    .signin-container{
        padding: 60px;
    }

    .intastellar-accounts-logo{
        margin-top: 90px;
        margin-bottom: 40px;
    }

    .graphic-container{
        display: none;
    }

    .key-numbers-section{
        display: grid;
        grid-template-columns: 1fr 1fr;
    }

    .used_by{
        width: 150px;
        margin: auto;
        display: flex;
    }
